SELECT o.order_id AS orderId, o.order_no AS orderNo, o.station_id AS stationId, s.station_name AS stationName, o.pile_code AS pileNo, CASE WHEN p.pile_type = 'dc' THEN '快充' WHEN p.pile_type = 'ac' THEN '慢充' ELSE p.pile_type END AS chargeType, o.start_time AS startTime, o.end_time AS endTime, o.duration, o.total_energy AS energy, o.total_amount AS amount, o.energy_price AS electricFee, o.service_price AS serviceFee, o.discount_amount AS discountAmount, o.order_status AS `status`, CASE WHEN o.order_status = '0' THEN '充电中' WHEN o.order_status = '1' THEN '已完成' WHEN o.order_status = '2' THEN '已取消' ELSE o.order_status END AS statusText, o.pay_status AS payStatus, o.create_time AS createTime, o.end_time AS endTimeVal FROM stad_charging_order o LEFT JOIN stad_charging_station s ON o.station_id = s.station_id LEFT JOIN stad_charging_pile p ON o.pile_id = p.pile_id WHERE o.user_id = #{userId}
AND o.order_status = #{status}
ORDER BY o.create_time DESC LIMIT #{offset}, #{limit}

SELECT COUNT(*) FROM stad_charging_order o
WHERE o.user_id = #{userId}

    AND o.order_status = #{status}

